local selector=np.array({{false,true,true,false},{true,true,false,true},{true,false,true,true}},"bool")
local values=np.array({false,true,false,true,false,true,false},"bool")
local ok,result=pcall(function() return np.putmask(a,selector,values) end)
assert(ok==true,"bool/plain/7/bool: acceptance")
if ok then assert(result==nil,"bool/plain/7/bool: return") end
eq(base:tolist(),{{false,true,false,true},{false,true,false,false},{true,true,true,false}},"bool/plain/7/bool")
eq(a.shape,{3,4},"bool/plain/7/bool: shape")
eq(a.strides,{4,1},"bool/plain/7/bool: strides")
cases=cases+1
end
